create extension if not exists pgcrypto;

create table if not exists users (id uuid primary key default gen_random_uuid(), email text not null unique, password_hash text not null, created_at timestamptz not null default now());
create table if not exists sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, token_hash text not null unique, expires_at timestamptz not null, created_at timestamptz not null default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references users(id), name text not null, description text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists project_members (project_id uuid not null references projects(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, role text not null default 'editor', primary key (project_id, user_id));
create table if not exists assets (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, kind text not null default 'image', name text not null, object_key text not null unique, uri text not null, mime_type text not null, size integer not null default 0, version integer not null default 1, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists canvas_nodes (id text not null, project_id uuid not null references projects(id) on delete cascade, node_type text not null, label text not null, position jsonb not null, data jsonb not null default '{}', status text not null default 'idle', updated_at timestamptz not null default now(), primary key (project_id, id));
create table if not exists canvas_edges (id text not null, project_id uuid not null references projects(id) on delete cascade, source_node_id text not null, target_node_id text not null, edge_type text not null default 'reference', data jsonb not null default '{}', primary key (project_id, id));
create table if not exists canvas_snapshots (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, version integer not null, nodes jsonb not null, edges jsonb not null, created_at timestamptz not null default now(), unique(project_id, version));
create table if not exists generation_jobs (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, node_id text not null, provider text not null, model_id text not null, mode text not null default 'edit', prompt text not null default '', input jsonb not null default '{}', parameters jsonb not null default '{}', status text not null default 'pending', progress integer not null default 0, error_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists job_events (id uuid primary key default gen_random_uuid(), job_id uuid not null references generation_jobs(id) on delete cascade, project_id uuid not null references projects(id) on delete cascade, status text not null, progress integer not null default 0, message text not null default '', created_at timestamptz not null default now());
create table if not exists job_artifacts (id uuid primary key default gen_random_uuid(), job_id uuid not null references generation_jobs(id) on delete cascade, uri text not null, mime_type text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists sessions_token_hash_idx on sessions(token_hash);
create index if not exists project_members_user_idx on project_members(user_id);
create index if not exists assets_project_idx on assets(project_id, created_at desc);
create index if not exists generation_jobs_project_idx on generation_jobs(project_id, created_at desc);
create index if not exists job_events_project_idx on job_events(project_id, created_at desc);
